-- Reforma: a história nova (quadros do desenho) em en, es, fr e it, e a cena de Worms no dilema 11-13 em todos os idiomas.
-- ANTES: rode kids-desenhos-reforma.sql (pt-BR) e confirme que quadros/reforma-1..4.webp está no ar.
-- railway connect 3minutes-db < docs/plano-melhorias/kids-desenhos-reforma-idiomas.sql
-- Se alguma faixa/idioma não existir, o script para e desfaz tudo. Revisão de texto (es, fr, it) é do editorial.
\set ON_ERROR_STOP on
BEGIN;
DO $$
BEGIN
  IF (SELECT count(*) FROM devotional_kids WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND language IN ('en','es','fr','it') AND band IN ('4-6','7-10')) <> 8 THEN
    RAISE EXCEPTION 'Esperava 8 versões (4-6 e 7-10 em en, es, fr, it); nada foi alterado.';
  END IF;
END $$;

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/reforma-protestante/quadros/reforma-1.webp", "caption": "Luther read the Bible very carefully and discovered God's love.", "speech": "God loves us for free!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-2.webp", "caption": "He shared what he found and put the message on the church door.", "speech": "Shall we talk about it?"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-3.webp", "caption": "In front of very important people, he wanted to stay faithful to the Bible.", "speech": "The Bible matters most!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-4.webp", "caption": "Later, families could read the Bible at home.", "speech": "Shall we read together?"}]}$j$::jsonb
 WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '4-6' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/reforma-protestante/quadros/reforma-1.webp", "caption": "Wittenberg, 1517. Studying Paul's letter, Luther discovered: forgiveness is a gift from God.", "speech": "You can't buy it. You receive it!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-2.webp", "caption": "He wrote down his questions and nailed them to the church door so everyone could talk.", "speech": "95 ideas to talk about!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-3.webp", "caption": "At Worms, he was asked to take back what he wrote. He answered that only the Bible could convince him.", "speech": "Only the Bible can convince me."}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-4.webp", "caption": "Later, the Bible was translated and printed, and ordinary families could read it.", "speech": "Now everyone can understand!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '7-10' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/reforma-protestante/quadros/reforma-1.webp", "caption": "Lutero leía la Biblia con mucha atención y descubrió el amor de Dios.", "speech": "¡Dios nos ama gratis!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-2.webp", "caption": "Contó lo que descubrió y puso el mensaje en la puerta de la iglesia.", "speech": "¿Hablamos de esto?"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-3.webp", "caption": "Ante personas muy importantes, quiso ser fiel a la Biblia.", "speech": "¡La Biblia es lo que más importa!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-4.webp", "caption": "Después, las familias pudieron leer la Biblia en casa.", "speech": "¿Leemos juntos?"}]}$j$::jsonb
 WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '4-6' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/reforma-protestante/quadros/reforma-1.webp", "caption": "Wittenberg, 1517. Estudiando la carta de Pablo, Lutero descubrió: el perdón es un regalo de Dios.", "speech": "¡No se compra. Se recibe!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-2.webp", "caption": "Escribió sus dudas y las clavó en la puerta de la iglesia para que todos conversaran.", "speech": "¡95 ideas para conversar!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-3.webp", "caption": "En Worms, le pidieron que negara lo que había escrito. Respondió que solo la Biblia podría convencerlo.", "speech": "Solo la Biblia puede convencerme."}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-4.webp", "caption": "Después, la Biblia fue traducida e impresa, y las familias comunes pudieron leerla.", "speech": "¡Ahora todos entienden!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '7-10' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/reforma-protestante/quadros/reforma-1.webp", "caption": "Luther lisait la Bible avec beaucoup d'attention et découvrit l'amour de Dieu.", "speech": "Dieu nous aime gratuitement !"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-2.webp", "caption": "Il raconta ce qu'il avait découvert et afficha le message sur la porte de l'église.", "speech": "On en parle ensemble ?"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-3.webp", "caption": "Devant des gens très importants, il voulut rester fidèle à la Bible.", "speech": "La Bible est ce qui compte le plus !"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-4.webp", "caption": "Plus tard, les familles purent lire la Bible à la maison.", "speech": "On lit ensemble ?"}]}$j$::jsonb
 WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '4-6' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/reforma-protestante/quadros/reforma-1.webp", "caption": "Wittenberg, 1517. En étudiant la lettre de Paul, Luther découvrit : le pardon est un cadeau de Dieu.", "speech": "Il ne s'achète pas. Il se reçoit !"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-2.webp", "caption": "Il écrivit ses questions et les cloua sur la porte de l'église pour que tout le monde en parle.", "speech": "95 idées pour discuter !"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-3.webp", "caption": "À Worms, on lui demanda de renier ce qu'il avait écrit. Il répondit que seule la Bible pourrait le convaincre.", "speech": "Seule la Bible peut me convaincre."}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-4.webp", "caption": "Plus tard, la Bible fut traduite et imprimée, et les familles ordinaires purent la lire.", "speech": "Maintenant, tout le monde comprend !"}]}$j$::jsonb
 WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '7-10' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/reforma-protestante/quadros/reforma-1.webp", "caption": "Lutero leggeva la Bibbia con molta attenzione e scoprì l'amore di Dio.", "speech": "Dio ci ama gratis!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-2.webp", "caption": "Raccontò ciò che aveva scoperto e affisse il messaggio sulla porta della chiesa.", "speech": "Ne parliamo insieme?"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-3.webp", "caption": "Davanti a persone molto importanti, volle restare fedele alla Bibbia.", "speech": "La Bibbia è ciò che conta di più!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-4.webp", "caption": "Più tardi, le famiglie poterono leggere la Bibbia a casa.", "speech": "Leggiamo insieme?"}]}$j$::jsonb
 WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '4-6' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/reforma-protestante/quadros/reforma-1.webp", "caption": "Wittenberg, 1517. Studiando la lettera di Paolo, Lutero scoprì: il perdono è un dono di Dio.", "speech": "Non si compra. Si riceve!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-2.webp", "caption": "Scrisse i suoi dubbi e li affisse sulla porta della chiesa perché tutti ne parlassero.", "speech": "95 idee di cui parlare!"}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-3.webp", "caption": "A Worms gli chiesero di rinnegare ciò che aveva scritto. Rispose che solo la Bibbia avrebbe potuto convincerlo.", "speech": "Solo la Bibbia può convincermi."}, {"image": "/ilustracoes/reforma-protestante/quadros/reforma-4.webp", "caption": "Poi la Bibbia fu tradotta e stampata, e le famiglie comuni poterono leggerla.", "speech": "Ora tutti capiscono!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '7-10' AND language = 'it';

UPDATE devotional_kids SET story = jsonb_set(story, '{image}', to_jsonb('/ilustracoes/reforma-protestante/quadros/reforma-3.webp'::text))
 WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '11-13' AND story->>'format' = 'dilemma';

SELECT language, band, story->>'format' AS formato, jsonb_array_length(story->'panels') AS quadros, story->>'image' AS cena
  FROM devotional_kids WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' ORDER BY language, band;
COMMIT;
